// Minimal local replacement for the `libc` crate API used by `os_mem`.
mod libc {
    pub use core::ffi::c_void;

    pub const PROT_NONE: i32 = 0;
    pub const PROT_READ: i32 = 1;
    pub const PROT_WRITE: i32 = 2;
    pub const MAP_PRIVATE: i32 = 0x02;
    pub const MAP_FAILED: *mut c_void = usize::MAX as *mut c_void;

    #[cfg(target_os = "macos")]
    pub const MAP_ANONYMOUS: i32 = 0x1000;
    #[cfg(not(target_os = "macos"))]
    pub const MAP_ANONYMOUS: i32 = 0x20;

    // macOS does not provide MAP_NORESERVE; zero leaves its flags unchanged.
    #[cfg(target_os = "macos")]
    pub const MAP_NORESERVE: i32 = 0;
    #[cfg(not(target_os = "macos"))]
    pub const MAP_NORESERVE: i32 = 0x4000;

    #[cfg(target_os = "macos")]
    pub const CLOCK_MONOTONIC: i32 = 6;
    #[cfg(not(target_os = "macos"))]
    pub const CLOCK_MONOTONIC: i32 = 1;

    #[repr(C)]
    pub struct timespec {
        pub tv_sec: i64,
        pub tv_nsec: i64,
    }

    extern "C" {
        pub fn mmap(
            addr: *mut c_void,
            len: usize,
            prot: i32,
            flags: i32,
            fd: i32,
            offset: isize,
        ) -> *mut c_void;
        pub fn mprotect(addr: *mut c_void, len: usize, prot: i32) -> i32;
        pub fn clock_gettime(clock_id: i32, ts: *mut timespec) -> i32;
    }
}

