            len,
            PROT_NONE,
            MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE,
            // The fd argument is ignored [if MAP_ANONYMOUS is specified]; however,
            // some implementations require fd to be -1
            -1,
            0)
    }
}

